export function p053ShapeDefsSvg(namespace:string):string{
  if(!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/u.test(namespace))throw new RangeError('P053 SVG namespace');
  return P053_SHAPE_DEFS_SVG.replace(/id="(p053-shape-[A-Za-z0-9_.-]+)"/gu,(_,id:string)=>`id="${namespace}-${id}"`)
    .replace(/url\(#(p053-shape-[A-Za-z0-9_.-]+)\)/gu,(_,id:string)=>`url(#${namespace}-${id})`);
}
export function p053ShapeSymbolId(characterId:number,namespace:string):string{
  if(!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/u.test(namespace))throw new RangeError('P053 SVG namespace');
  const id=P053_SHAPE_SYMBOL_IDS[String(characterId) as keyof typeof P053_SHAPE_SYMBOL_IDS];
  if(!id)throw new RangeError('Unknown P053 source shape');
  return `${namespace}-${id}`;
}
export function namespaceP053ShapeArt(namespace:string):{defsSvg:string;symbolIds:Readonly<Record<number,string>>}{
  const defsSvg=p053ShapeDefsSvg(namespace);
  const symbolIds=Object.fromEntries(Object.keys(P053_SHAPE_SYMBOL_IDS).map(id=>
    [Number(id),p053ShapeSymbolId(Number(id),namespace)])) as Readonly<Record<number,string>>;
  return {defsSvg,symbolIds:Object.freeze(symbolIds)};
}
